__modules["Util"] = function()
	--[[
		Util
		----
		Small dependency-free helpers. Pure functions only: everything in here is
		directly unit tested by the offline harness.
	]]

	local Util = {}

	--- Wraps `fn` so it can never throw into the caller. Returns ok, result...
	function Util.try(fn, ...)
		if type(fn) ~= "function" then
			return false, "not a function"
		end
		return pcall(fn, ...)
	end

	--- pcall that logs nothing and returns `default` on failure.
	function Util.attempt(default, fn, ...)
		local ok, result = pcall(fn, ...)
		if ok and result ~= nil then
			return result
		end
		return default
	end

	--- Formats a per-second income figure using short SI-ish suffixes.
	function Util.formatGeneration(value)
		value = tonumber(value) or 0
		local negative = value < 0
		local n = math.abs(value)

		local text
		if n >= 1e15 then
			text = string.format("%.1fQ", n / 1e15)
		elseif n >= 1e12 then
			text = string.format("%.1fT", n / 1e12)
		elseif n >= 1e9 then
			text = string.format("%.1fB", n / 1e9)
		elseif n >= 1e6 then
			text = string.format("%.1fM", n / 1e6)
		elseif n >= 1e3 then
			text = string.format("%.1fK", n / 1e3)
		else
			text = tostring(math.floor(n))
		end

		-- Trim a trailing ".0" so "$1.0M/s" renders as "$1M/s".
		text = text:gsub("%.0(%a)$", "%1")

		return string.format("$%s%s/s", negative and "-" or "", text)
	end

	--- Truncates `text` to `limit` characters, appending an ellipsis.
	function Util.truncate(text, limit)
		text = tostring(text or "")
		limit = limit or 15
		if #text <= limit then
			return text
		end
		if limit <= 1 then
			return text:sub(1, limit)
		end
		return text:sub(1, limit - 1) .. "…"
	end

	--- Case-insensitive subsequence match used by the search box.
	--- "dgc" matches "Dragon Cannelloni"; a plain substring also matches.
	function Util.fuzzyMatch(haystack, needle)
		if needle == nil or needle == "" then
			return true
		end
		haystack = tostring(haystack):lower()
		needle = tostring(needle):lower()

		if haystack:find(needle, 1, true) then
			return true
		end

		local cursor = 1
		for index = 1, #needle do
			local char = needle:sub(index, index)
			if char ~= " " then
				local found = haystack:find(char, cursor, true)
				if not found then
					return false
				end
				cursor = found + 1
			end
		end
		return true
	end

	--- Ranks matches so exact / prefix hits float to the top of the list.
	function Util.matchScore(haystack, needle)
		if needle == nil or needle == "" then
			return 0
		end
		local lowerHay = tostring(haystack):lower()
		local lowerNeedle = tostring(needle):lower()

		if lowerHay == lowerNeedle then
			return 100
		end
		if lowerHay:sub(1, #lowerNeedle) == lowerNeedle then
			return 75
		end
		local at = lowerHay:find(lowerNeedle, 1, true)
		if at then
			return 50 - math.min(at, 25)
		end
		if Util.fuzzyMatch(lowerHay, lowerNeedle) then
			return 10
		end
		return -1
	end

	--- Filters + ranks a list of names against a query.
	function Util.searchNames(names, query)
		local results = {}
		for _, name in ipairs(names) do
			local score = Util.matchScore(name, query)
			if score >= 0 then
				results[#results + 1] = { name = name, score = score }
			end
		end
		table.sort(results, function(a, b)
			if a.score ~= b.score then
				return a.score > b.score
			end
			return a.name < b.name
		end)

		local names2 = {}
		for index, entry in ipairs(results) do
			names2[index] = entry.name
		end
		return names2
	end

	--- Shallow copy; used so callers cannot mutate module level tables.
	function Util.shallowCopy(source)
		local out = {}
		for key, value in pairs(source) do
			out[key] = value
		end
		return out
	end

	--- Returns true when `value` is one of the entries in `list`.
	function Util.contains(list, value)
		for _, entry in ipairs(list) do
			if entry == value then
				return true
			end
		end
		return false
	end

	--- Clamps a number into a range.
	function Util.clamp(value, min, max)
		if value < min then
			return min
		elseif value > max then
			return max
		end
		return value
	end

	return Util
end

__modules["Log"] = function()
	--[[
		Log
		---
		Levelled logging with a ring buffer.

		The original script printed emoji straight to the console from a dozen
		call sites, which made it impossible to silence, filter, or surface
		messages inside the GUI. Everything now flows through here:

			Log.info("plot", "found %s at %d studs", plot.Name, dist)

		* `Log.level` gates what reaches the console.
		* `Log.history` keeps the last N records so the UI can show a status line
		  or a debug pane without re-plumbing every call site.
		* `Log.onMessage` lets one listener (the GUI) mirror output.
	]]

	local Config = __require("Config")

	local Log = {}

	Log.Level = {
		TRACE = 10,
		DEBUG = 20,
		INFO = 30,
		WARN = 40,
		ERROR = 50,
		NONE = 100,
	}

	local LEVEL_NAME = {
		[Log.Level.TRACE] = "TRACE",
		[Log.Level.DEBUG] = "DEBUG",
		[Log.Level.INFO] = "INFO",
		[Log.Level.WARN] = "WARN",
		[Log.Level.ERROR] = "ERROR",
	}

	Log.level = Log.Level.INFO
	Log.history = {}
	Log.historyLimit = 200
	Log.onMessage = nil

	local function timestamp()
		local ok, clock = pcall(os.clock)
		return ok and clock or 0
	end

	--- Formats safely: a stray `%` in user data must never error the caller.
	local function safeFormat(message, ...)
		if select("#", ...) == 0 then
			return message
		end
		local ok, formatted = pcall(string.format, message, ...)
		return ok and formatted or message
	end

	local function record(level, scope, message, ...)
		local text = safeFormat(message, ...)
		local entry = {
			level = level,
			levelName = LEVEL_NAME[level] or "LOG",
			scope = scope or "app",
			message = text,
			clock = timestamp(),
		}

		local history = Log.history
		history[#history + 1] = entry
		if #history > Log.historyLimit then
			table.remove(history, 1)
		end

		if level >= Log.level then
			local line = string.format("[%s][%s] %s", Config.APP_NAME, entry.scope, text)
			if level >= Log.Level.ERROR then
				pcall(warn, line)
			else
				pcall(print, line)
			end
		end

		if Log.onMessage then
			pcall(Log.onMessage, entry)
		end

		return entry
	end

	function Log.trace(scope, message, ...)
		return record(Log.Level.TRACE, scope, message, ...)
	end

	function Log.debug(scope, message, ...)
		return record(Log.Level.DEBUG, scope, message, ...)
	end

	function Log.info(scope, message, ...)
		return record(Log.Level.INFO, scope, message, ...)
	end

	function Log.warn(scope, message, ...)
		return record(Log.Level.WARN, scope, message, ...)
	end

	function Log.error(scope, message, ...)
		return record(Log.Level.ERROR, scope, message, ...)
	end

	--- Clears the ring buffer (used by tests).
	function Log.clear()
		table.clear(Log.history)
	end

	return Log
end

__modules["Signal"] = function()
	--[[
		Signal
		------
		Minimal observer used to decouple the controllers from the GUI. Listeners
		are isolated with pcall so one broken handler cannot stop the rest.
	]]

	local Signal = {}
	Signal.__index = Signal

	function Signal.new(name)
		return setmetatable({
			_name = name or "signal",
			_handlers = {},
		}, Signal)
	end

	--- Registers `handler`; returns a disconnect function.
	function Signal:connect(handler)
		assert(type(handler) == "function", "Signal:connect expects a function")
		local handlers = self._handlers
		handlers[#handlers + 1] = handler

		return function()
			for index, candidate in ipairs(handlers) do
				if candidate == handler then
					table.remove(handlers, index)
					break
				end
			end
		end
	end

	--- Calls every listener. Errors are swallowed and returned as a count.
	function Signal:fire(...)
		local failures = 0
		-- Iterate a copy so a listener may disconnect during dispatch.
		local snapshot = {}
		for index, value in ipairs(self._handlers) do
			snapshot[index] = value
		end

		for _, handler in ipairs(snapshot) do
			local ok = pcall(handler, ...)
			if not ok then
				failures = failures + 1
			end
		end
		return failures
	end

	function Signal:destroy()
		table.clear(self._handlers)
	end

	return Signal
end

__modules["Env"] = function()
	--[[
		Env
		---
		Every direct touch of a Roblox service or an executor global lives here.

		Two reasons:
		  1. The rest of the codebase stays loadable by the offline test harness,
		     which injects a fake `Env`.
		  2. Executor differences (gethui, hookfunction, getgenv, http_request)
		     are probed exactly once instead of being re-pcall'd at every site.
	]]

	local Env = {}

	--- GetService that survives `game` being absent entirely (test harness) and
	--- a service being unavailable (some executors block CoreGui).
	local function service(name)
		local ok, result = pcall(function()
			return game:GetService(name)
		end)
		return ok and result or nil
	end

	Env.Players = service("Players")
	Env.UserInputService = service("UserInputService")
	Env.RunService = service("RunService")
	Env.ReplicatedStorage = service("ReplicatedStorage")
	Env.Workspace = service("Workspace") or rawget(_G, "workspace")
	Env.CoreGui = service("CoreGui")
	Env.TweenService = service("TweenService")
	Env.HttpService = service("HttpService")

	Env.LocalPlayer = Env.Players and Env.Players.LocalPlayer or nil

	------------------------------------------------------------------------------
	-- Executor capability probe
	------------------------------------------------------------------------------

	local function capability(name)
		local ok, value = pcall(function()
			local scope = getfenv and getfenv(0) or _G
			return rawget(scope, name)
		end)
		if ok and type(value) == "function" then
			return value
		end
		return nil
	end

	Env.Capabilities = {
		gethui = capability("gethui"),
		getgenv = capability("getgenv"),
		httpRequest = capability("http_request") or capability("request"),
		getNilInstances = capability("getnilinstances"),
		fireSignal = capability("firesignal"),
	}

	--- True when running under an exploit executor rather than a plain client.
	Env.IsExecutor = Env.Capabilities.getgenv ~= nil or Env.Capabilities.gethui ~= nil

	--- Shared global table. Falls back to a module-local table so the same-machine
	--- transport degrades gracefully instead of erroring.
	local fallbackGlobals = {}
	function Env.globals()
		local getgenv = Env.Capabilities.getgenv
		if getgenv then
			local ok, result = pcall(getgenv)
			if ok and type(result) == "table" then
				return result
			end
		end
		return fallbackGlobals
	end

	------------------------------------------------------------------------------
	-- GUI parenting
	------------------------------------------------------------------------------

	--- Most protected place available for a ScreenGui, in descending preference.
	function Env.guiParent()
		local gethui = Env.Capabilities.gethui
		if gethui then
			local ok, hidden = pcall(gethui)
			if ok and hidden then
				return hidden
			end
		end

		if Env.LocalPlayer then
			local ok, playerGui = pcall(function()
				return Env.LocalPlayer:WaitForChild("PlayerGui", 5)
			end)
			if ok and playerGui then
				return playerGui
			end
		end

		return Env.CoreGui
	end

	------------------------------------------------------------------------------
	-- Convenience accessors
	------------------------------------------------------------------------------

	--- Walks a path of child names from `root`, returning nil at the first miss.
	function Env.resolve(root, path)
		local node = root
		for _, name in ipairs(path) do
			if not node then
				return nil
			end
			local ok, child = pcall(node.FindFirstChild, node, name)
			if not ok then
				return nil
			end
			node = child
		end
		return node
	end

	--- require() that never throws.
	function Env.safeRequire(instance)
		if not instance then
			return nil
		end
		local ok, module = pcall(require, instance)
		if ok then
			return module
		end
		return nil
	end

	--- Character root part, or nil while respawning.
	function Env.rootPart()
		local player = Env.LocalPlayer
		if not player then
			return nil
		end
		local character = player.Character
		if not character then
			return nil
		end
		return character:FindFirstChild("HumanoidRootPart")
	end

	--- Monotonic-ish clock that works in both Roblox and the harness.
	function Env.now()
		local ok, value = pcall(os.clock)
		if ok then
			return value
		end
		return 0
	end

	return Env
end

__modules["Protocol"] = function()
	--[[
		Protocol
		--------
		Pure payload construction and validation for the admin -> tester link.

		Keeping this free of Roblox types means every rule (revision checks,
		staleness, replay rejection, slot validation) is unit tested offline.

		Wire shape:
			{
				protocol = 2,          -- integer, must match Config.Sync.Protocol
				slot     = "Main",     -- one of Config.Slots
				brainrot = "Griffin",  -- name; "" clears the slot
				sequence = 17,         -- monotonic per session, rejects replays
				session  = "a1b2c3",   -- identifies the broadcasting admin
				sentAt   = 1234.5,     -- sender clock, used for staleness display
			}
	]]

	local Config = __require("Config")
	local Util = __require("Util")

	local Protocol = {}

	Protocol.REVISION = Config.Sync.Protocol

	--- Builds a well formed payload. `sequence` must increase per session.
	function Protocol.encode(slot, brainrot, sequence, session, sentAt)
		return {
			protocol = Protocol.REVISION,
			slot = slot,
			brainrot = brainrot or "",
			sequence = sequence,
			session = session,
			sentAt = sentAt,
		}
	end

	--- Validates an inbound payload.
	--- Returns `true, payload` or `false, reason`.
	function Protocol.validate(payload)
		if type(payload) ~= "table" then
			return false, "payload is not a table"
		end

		if payload.protocol ~= Protocol.REVISION then
			return false, string.format(
				"protocol mismatch (got %s, want %d)",
				tostring(payload.protocol),
				Protocol.REVISION
			)
		end

		if type(payload.slot) ~= "string" or not Util.contains(Config.Slots, payload.slot) then
			return false, "unknown slot " .. tostring(payload.slot)
		end

		if type(payload.brainrot) ~= "string" then
			return false, "brainrot must be a string"
		end

		-- An empty name is the documented "clear this slot" instruction.
		if payload.brainrot ~= "" and not Config.BrainrotSet[payload.brainrot] then
			return false, "unknown brainrot " .. payload.brainrot
		end

		if type(payload.sequence) ~= "number" or payload.sequence < 0 then
			return false, "sequence must be a non-negative number"
		end

		if type(payload.session) ~= "string" or payload.session == "" then
			return false, "missing session id"
		end

		return true, payload
	end

	--- Decides whether `payload` supersedes what we already applied.
	--- `state` is a table of { session = string?, sequence = number? }.
	function Protocol.isNewer(state, payload)
		if not state or state.session ~= payload.session then
			-- A different admin took over; always accept the first message.
			return true
		end
		return payload.sequence > (state.sequence or -1)
	end

	--- True when the payload is older than Config.Behaviour.StaleAfter.
	function Protocol.isStale(payload, now)
		if type(payload) ~= "table" or type(payload.sentAt) ~= "number" then
			return true
		end
		return (now - payload.sentAt) > Config.Behaviour.StaleAfter
	end

	--- Flattens a payload into the attribute pairs used by the folder transport.
	function Protocol.toAttributes(payload)
		return {
			Protocol = payload.protocol,
			Slot = payload.slot,
			Brainrot = payload.brainrot,
			Sequence = payload.sequence,
			Session = payload.session,
			SentAt = payload.sentAt,
		}
	end

	--- Inverse of `toAttributes`.
	function Protocol.fromAttributes(attributes)
		if type(attributes) ~= "table" then
			return nil
		end
		return {
			protocol = attributes.Protocol,
			slot = attributes.Slot,
			brainrot = attributes.Brainrot,
			sequence = attributes.Sequence,
			session = attributes.Session,
			sentAt = attributes.SentAt,
		}
	end

	--- Short random session identifier, no HttpService dependency.
	function Protocol.newSessionId()
		local chars = "0123456789abcdef"
		local out = {}
		for index = 1, 8 do
			local pick = math.random(1, #chars)
			out[index] = chars:sub(pick, pick)
		end
		return table.concat(out)
	end

	return Protocol
end

__modules["Transport"] = function()
	--[[
		Transport
		---------
		Pluggable delivery channels for sync payloads.

		IMPORTANT CORRECTNESS NOTE
		--------------------------
		The original script created folders and set attributes on ReplicatedStorage
		and Workspace *from the client*. Client-created instances and client-set
		attributes DO NOT replicate to the server, and therefore never reach a
		second player's client. That transport can only ever work when both scripts
		run inside the same client.

		Genuine cross-client delivery requires the server to relay the message, so
		the only honest options are:

		  * Global    - same machine, two script tabs. Always reliable.
		  * Folder    - same client, survives script restarts. Legacy compatible.
		  * Remote    - fires an existing game RemoteEvent so the SERVER relays it.
		                Works across machines only if the game happens to expose a
		                remote that echoes arbitrary data to other players. Most
		                games do not, and firing unknown remotes is detectable.

		`Transport.remote` therefore probes for a candidate, reports honestly
		whether it found one, and never pretends to have delivered anything.
	]]

	local Config = __require("Config")
	local Env = __require("Env")
	local Log = __require("Log")
	local Protocol = __require("Protocol")

	local Transport = {}

	------------------------------------------------------------------------------
	-- Global transport: shared getgenv() table, same machine only.
	------------------------------------------------------------------------------

	local Global = {}
	Global.__index = Global
	Global.id = "global"
	Global.crossClient = false

	function Global.new()
		return setmetatable({}, Global)
	end

	function Global:isAvailable()
		return true
	end

	function Global:send(payload)
		local globals = Env.globals()
		local bucket = globals[Config.Sync.GlobalKey]
		if type(bucket) ~= "table" then
			bucket = { listeners = {} }
			globals[Config.Sync.GlobalKey] = bucket
		end
		bucket.latest = payload

		for _, listener in ipairs(bucket.listeners) do
			pcall(listener, payload)
		end
		return true
	end

	function Global:subscribe(handler)
		local globals = Env.globals()
		local bucket = globals[Config.Sync.GlobalKey]
		if type(bucket) ~= "table" then
			bucket = { listeners = {} }
			globals[Config.Sync.GlobalKey] = bucket
		end

		table.insert(bucket.listeners, handler)

		-- Replay whatever the admin already published so a late tester catches up.
		if bucket.latest then
			pcall(handler, bucket.latest)
		end

		return function()
			for index, candidate in ipairs(bucket.listeners) do
				if candidate == handler then
					table.remove(bucket.listeners, index)
					break
				end
			end
		end
	end

	Transport.Global = Global

	------------------------------------------------------------------------------
	-- Folder transport: attributes on a ReplicatedStorage folder.
	------------------------------------------------------------------------------

	local Folder = {}
	Folder.__index = Folder
	Folder.id = "folder"
	Folder.crossClient = false

	function Folder.new()
		return setmetatable({ _connections = {} }, Folder)
	end

	function Folder:_folder()
		local parent = Env.ReplicatedStorage
		if not parent then
			return nil
		end
		local existing = parent:FindFirstChild(Config.Sync.Channel)
		if existing then
			return existing
		end
		local ok, created = pcall(function()
			local folder = Instance.new("Folder")
			folder.Name = Config.Sync.Channel
			folder.Parent = parent
			return folder
		end)
		return ok and created or nil
	end

	function Folder:isAvailable()
		return self:_folder() ~= nil
	end

	function Folder:send(payload)
		local folder = self:_folder()
		if not folder then
			return false
		end
		local attributes = Protocol.toAttributes(payload)
		for key, value in pairs(attributes) do
			pcall(folder.SetAttribute, folder, key, value)
		end
		return true
	end

	function Folder:subscribe(handler)
		local folder = self:_folder()
		if not folder then
			return function() end
		end

		local function emit()
			local attributes = {}
			local ok, map = pcall(folder.GetAttributes, folder)
			if ok and type(map) == "table" then
				for key, value in pairs(map) do
					attributes[key] = value
				end
			end
			local payload = Protocol.fromAttributes(attributes)
			if payload then
				pcall(handler, payload)
			end
		end

		local connection = folder:GetAttributeChangedSignal("Sequence"):Connect(emit)
		table.insert(self._connections, connection)

		emit()

		return function()
			pcall(function()
				connection:Disconnect()
			end)
		end
	end

	Transport.Folder = Folder

	------------------------------------------------------------------------------
	-- Remote transport: relay through a server owned RemoteEvent.
	------------------------------------------------------------------------------

	local Remote = {}
	Remote.__index = Remote
	Remote.id = "remote"
	Remote.crossClient = true

	function Remote.new()
		return setmetatable({ _cached = nil, _searched = false }, Remote)
	end

	--- Breadth-first hunt for a RemoteEvent whose name matches a configured hint.
	function Remote:_discover()
		if self._searched then
			return self._cached
		end
		self._searched = true

		local root = Env.ReplicatedStorage
		if not root then
			return nil
		end

		local queue = { { node = root, depth = 0 } }
		local head = 1

		while head <= #queue do
			local item = queue[head]
			head = head + 1

			local ok, children = pcall(item.node.GetChildren, item.node)
			if ok then
				for _, child in ipairs(children) do
					local isRemote = false
					pcall(function()
						isRemote = child:IsA("RemoteEvent")
					end)

					if isRemote then
						for _, hint in ipairs(Config.Sync.RemoteHints) do
							if child.Name == hint then
								self._cached = child
								Log.info("sync", "remote transport bound to %s", child:GetFullName())
								return child
							end
						end
					elseif item.depth < Config.Sync.RemoteSearchDepth then
						queue[#queue + 1] = { node = child, depth = item.depth + 1 }
					end
				end
			end
		end

		Log.warn("sync", "no relay RemoteEvent found; cross-client sync unavailable")
		return nil
	end

	function Remote:isAvailable()
		return self:_discover() ~= nil
	end

	function Remote:send(payload)
		local remote = self:_discover()
		if not remote then
			return false
		end
		local ok = pcall(function()
			remote:FireServer(Config.Sync.Channel, payload)
		end)
		if not ok then
			Log.warn("sync", "remote FireServer failed")
		end
		return ok
	end

	function Remote:subscribe(handler)
		local remote = self:_discover()
		if not remote then
			return function() end
		end

		local connection = remote.OnClientEvent:Connect(function(channel, payload)
			if channel == Config.Sync.Channel then
				pcall(handler, payload)
			end
		end)

		return function()
			pcall(function()
				connection:Disconnect()
			end)
		end
	end

	Transport.Remote = Remote

	------------------------------------------------------------------------------

	--- Builds the default transport stack, best delivery guarantee first.
	function Transport.defaults()
		return { Remote.new(), Global.new(), Folder.new() }
	end

	return Transport
end

__modules["Sync"] = function()
	--[[
		Sync
		----
		Fans a payload out across every available transport and, on the receiving
		end, de-duplicates what comes back in.

		The admin publishes; the tester subscribes. Both sides share this object so
		the sequencing and replay rules live in exactly one place.
	]]

	local Config = __require("Config")
	local Env = __require("Env")
	local Log = __require("Log")
	local Protocol = __require("Protocol")
	local Signal = __require("Signal")
	local Transport = __require("Transport")

	local Sync = {}
	Sync.__index = Sync

	function Sync.new(options)
		options = options or {}

		local self = setmetatable({
			transports = options.transports or Transport.defaults(),
			session = options.session or Protocol.newSessionId(),
			clock = options.clock or Env.now,
			_sequence = 0,
			_last = nil,
			_applied = { session = nil, sequence = -1 },
			_unsubscribers = {},
			_heartbeat = nil,
			received = Signal.new("sync.received"),
			rejected = Signal.new("sync.rejected"),
		}, Sync)

		return self
	end

	--- Transports that reported themselves usable, cheapest check first.
	function Sync:activeTransports()
		local active = {}
		for _, transport in ipairs(self.transports) do
			local ok, available = pcall(transport.isAvailable, transport)
			if ok and available then
				active[#active + 1] = transport
			end
		end
		return active
	end

	--- True when at least one transport can reach another machine.
	function Sync:hasCrossClient()
		for _, transport in ipairs(self:activeTransports()) do
			if transport.crossClient then
				return true
			end
		end
		return false
	end

	------------------------------------------------------------------------------
	-- Publishing
	------------------------------------------------------------------------------

	--- Publishes a slot assignment. Returns the payload and a delivery report.
	function Sync:publish(slot, brainrot)
		self._sequence = self._sequence + 1

		local payload = Protocol.encode(
			slot,
			brainrot,
			self._sequence,
			self.session,
			self.clock()
		)

		local ok, reason = Protocol.validate(payload)
		if not ok then
			Log.error("sync", "refusing to publish invalid payload: %s", reason)
			return nil, { delivered = 0, attempted = 0 }
		end

		self._last = payload
		return payload, self:_deliver(payload)
	end

	function Sync:_deliver(payload)
		local report = { delivered = 0, attempted = 0, byTransport = {} }

		for _, transport in ipairs(self.transports) do
			local available = select(2, pcall(transport.isAvailable, transport))
			if available then
				report.attempted = report.attempted + 1
				local sent = select(2, pcall(transport.send, transport, payload))
				report.byTransport[transport.id] = sent and true or false
				if sent then
					report.delivered = report.delivered + 1
				end
			end
		end

		if report.delivered == 0 then
			Log.warn("sync", "payload reached no transport")
		else
			Log.debug("sync", "published %s=%s via %d transport(s)",
				payload.slot, payload.brainrot, report.delivered)
		end

		return report
	end

	--- Re-sends the most recent payload so late joiners converge.
	function Sync:republish()
		if not self._last then
			return false
		end
		self._last.sentAt = self.clock()
		self:_deliver(self._last)
		return true
	end

	--- Starts a background heartbeat that keeps republishing `_last`.
	function Sync:startHeartbeat(interval)
		if self._heartbeat then
			return
		end
		interval = interval or Config.Behaviour.HeartbeatInterval
		self._heartbeat = true

		task.spawn(function()
			while self._heartbeat do
				task.wait(interval)
				if self._heartbeat then
					pcall(function()
						self:republish()
					end)
				end
			end
		end)
	end

	function Sync:stopHeartbeat()
		self._heartbeat = nil
	end

	------------------------------------------------------------------------------
	-- Receiving
	------------------------------------------------------------------------------

	--- Runs an inbound payload through validation + replay rules.
	--- Returns true when it was accepted and the `received` signal fired.
	function Sync:ingest(payload)
		local ok, reasonOrPayload = Protocol.validate(payload)
		if not ok then
			self.rejected:fire(payload, reasonOrPayload)
			Log.trace("sync", "rejected payload: %s", reasonOrPayload)
			return false
		end

		-- Never react to our own broadcast.
		if payload.session == self.session then
			return false
		end

		if not Protocol.isNewer(self._applied, payload) then
			return false
		end

		self._applied = { session = payload.session, sequence = payload.sequence }
		self._last = payload
		self.received:fire(payload)
		return true
	end

	--- Subscribes to every available transport. Returns a disconnect function.
	function Sync:listen()
		self:disconnect()

		for _, transport in ipairs(self.transports) do
			local available = select(2, pcall(transport.isAvailable, transport))
			if available then
				local ok, unsubscribe = pcall(transport.subscribe, transport, function(payload)
					self:ingest(payload)
				end)
				if ok and type(unsubscribe) == "function" then
					table.insert(self._unsubscribers, unsubscribe)
				end
			end
		end

		Log.info("sync", "listening on %d transport(s)", #self._unsubscribers)

		return function()
			self:disconnect()
		end
	end

	function Sync:disconnect()
		for _, unsubscribe in ipairs(self._unsubscribers) do
			pcall(unsubscribe)
		end
		table.clear(self._unsubscribers)
	end

	--- Most recently published or accepted payload.
	function Sync:last()
		return self._last
	end

	--- True when nothing has arrived recently.
	function Sync:isStale()
		if not self._last then
			return true
		end
		return Protocol.isStale(self._last, self.clock())
	end

	function Sync:destroy()
		self:stopHeartbeat()
		self:disconnect()
		self.received:destroy()
		self.rejected:destroy()
	end

	return Sync
end

__modules["Catalogue"] = function()
	--[[
		Catalogue
		---------
		Brainrot metadata: generation figures, model lookup, animation lookup.

		The original code re-`require`d the game's data module on every single list
		row (65 requires per keystroke while searching). Results are memoised here.
	]]

	local Config = __require("Config")
	local Env = __require("Env")
	local Log = __require("Log")
	local Util = __require("Util")

	local Catalogue = {}

	local generationCache = {}
	local animalData = nil
	local assetModule = nil
	local loaded = false

	local function load()
		if loaded then
			return
		end
		loaded = true

		local rs = Env.ReplicatedStorage
		if not rs then
			return
		end

		animalData = Env.safeRequire(Env.resolve(rs, Config.Paths.AnimalData))
		assetModule = Env.safeRequire(Env.resolve(rs, Config.Paths.BrainrotAssets))

		if not animalData then
			Log.debug("catalogue", "animal data module unavailable; generations show as $0/s")
		end
	end

	--- Every known brainrot name, alphabetically.
	function Catalogue.names()
		return Config.Brainrots
	end

	function Catalogue.exists(name)
		return Config.BrainrotSet[name] == true
	end

	--- Income per second for `name`, memoised. Returns 0 when unknown.
	function Catalogue.generation(name)
		if generationCache[name] ~= nil then
			return generationCache[name]
		end

		load()

		local value = 0
		if animalData and type(animalData) == "table" then
			local entry = animalData[name]
			if type(entry) == "table" and tonumber(entry.Generation) then
				value = tonumber(entry.Generation)
			end
		end

		generationCache[name] = value
		return value
	end

	--- Pre-formatted "$1.2M/s" string for `name`.
	function Catalogue.generationText(name)
		return Util.formatGeneration(Catalogue.generation(name))
	end

	--- Returns a fresh clone of the display model, or nil.
	function Catalogue.model(name)
		load()

		if assetModule and type(assetModule.getModel) == "function" then
			local ok, resolved = pcall(assetModule.getModel, name)
			if ok and resolved then
				local cloneOk, clone = pcall(resolved.Clone, resolved)
				if cloneOk and clone then
					return clone
				end
			end
		end

		local rs = Env.ReplicatedStorage
		if rs then
			local folder = Env.resolve(rs, Config.Paths.ModelsFolder)
			local template = folder and folder:FindFirstChild(name)
			if template then
				local ok, clone = pcall(template.Clone, template)
				if ok then
					return clone
				end
			end
		end

		Log.warn("catalogue", "no model available for %s", name)
		return nil
	end

	--- Idle Animation instance for `name`, or nil.
	function Catalogue.idleAnimation(name)
		local rs = Env.ReplicatedStorage
		if not rs then
			return nil
		end
		local folder = Env.resolve(rs, Config.Paths.AnimationsFolder)
		local perAnimal = folder and folder:FindFirstChild(name)
		return perAnimal and perAnimal:FindFirstChild("Idle") or nil
	end

	--- Drops memoised values; call after a game update.
	function Catalogue.invalidate()
		table.clear(generationCache)
		animalData = nil
		assetModule = nil
		loaded = false
	end

	return Catalogue
end

__modules["PlotService"] = function()
	--[[
		PlotService
		-----------
		Locating the local player's plot and clearing brainrots from it.

		SAFETY REWRITE
		--------------
		The original cleaner iterated every top level model in Workspace and
		deleted anything within 60 studs of the plot pivot that had a Humanoid or
		an AnimationController. On a crowded server that happily deleted other
		players' characters, NPCs and vendors, because a player character is a
		Model with a Humanoid.

		`classify` below is a pure function with an explicit, ordered rule set and
		a hard exclusion list for player characters. It returns a decision plus the
		rule that fired, so the behaviour is unit tested and auditable.
	]]

	local Config = __require("Config")
	local Env = __require("Env")
	local Log = __require("Log")

	local PlotService = {}

	------------------------------------------------------------------------------
	-- Pure classification
	------------------------------------------------------------------------------

	--[[
		`subject` describes a candidate model without referencing Roblox types:
			{
				name             = string,
				isPlayerCharacter= boolean,
				isSpawnedMarker  = boolean,  -- KVSpawned attribute
				inPodiumsFolder  = boolean,
				distanceToPodium = number?,  -- nil when there are no podiums
				distanceToPlot   = number?,
				hasHumanoid      = boolean,
				isKnownBrainrot  = boolean,
			}

		Returns: remove (boolean), rule (string)
	]]
	function PlotService.classify(subject)
		-- Rule 0: never touch a player character. Highest precedence, no override.
		if subject.isPlayerCharacter then
			return false, "player-character"
		end

		-- Rule 1: explicit marker set by the game on spawned brainrots.
		if subject.isSpawnedMarker then
			return true, "kv-spawned"
		end

		-- Rule 2: parented under the plot's podium folder.
		if subject.inPodiumsFolder then
			return true, "in-podiums"
		end

		-- Rule 3: sitting on one of our podium spawn pads.
		local podiumDistance = subject.distanceToPodium
		if podiumDistance and podiumDistance < Config.Behaviour.PodiumRadius then
			return true, "on-podium"
		end

		-- Rule 4: a *named* brainrot loose inside our plot radius. Unlike the old
		-- code this requires the name to be in the catalogue; "has a Humanoid" is
		-- no longer sufficient on its own.
		local plotDistance = subject.distanceToPlot
		if subject.isKnownBrainrot and plotDistance and plotDistance < Config.Behaviour.PlotRadius then
			return true, "named-in-plot"
		end

		return false, "keep"
	end

	------------------------------------------------------------------------------
	-- Roblox bound helpers
	------------------------------------------------------------------------------

	local function characterSet()
		local set = {}
		local players = Env.Players
		if not players then
			return set
		end
		local ok, list = pcall(players.GetPlayers, players)
		if ok then
			for _, player in ipairs(list) do
				if player.Character then
					set[player.Character] = true
				end
			end
		end
		return set
	end

	--- Nearest plot model to the local character, or nil.
	function PlotService.findPlot()
		local plots = Env.Workspace and Env.Workspace:FindFirstChild(Config.Paths.PlotsFolder)
		if not plots then
			Log.warn("plot", "no %s folder in Workspace", Config.Paths.PlotsFolder)
			return nil
		end

		local root = Env.rootPart()
		if not root then
			Log.warn("plot", "character not ready")
			return nil
		end

		local origin = root.Position
		local best, bestDistance = nil, math.huge

		for _, plot in ipairs(plots:GetChildren()) do
			if plot:IsA("Model") then
				for _, marker in ipairs(PlotService.plotMarkers(plot)) do
					local distance = (marker.Position - origin).Magnitude
					if distance < bestDistance then
						bestDistance, best = distance, plot
					end
				end
			end
		end

		if best then
			Log.debug("plot", "matched %s at %d studs", best.Name, math.floor(bestDistance))
		else
			Log.warn("plot", "no plot matched; stand on your plot and retry")
		end

		return best, bestDistance
	end

	--- Reference parts belonging to a plot (spawn, root, podium pads).
	function PlotService.plotMarkers(plot)
		local markers = {}
		if not plot then
			return markers
		end

		for _, name in ipairs({ "Spawn", "MainRoot" }) do
			local part = plot:FindFirstChild(name)
			if part and part:IsA("BasePart") then
				markers[#markers + 1] = part
			end
		end

		for _, pad in ipairs(PlotService.podiumPads(plot)) do
			markers[#markers + 1] = pad
		end

		return markers
	end

	--- Spawn pads inside the plot's podium folder.
	function PlotService.podiumPads(plot)
		local pads = {}
		local podiums = plot and plot:FindFirstChild(Config.Paths.PodiumsFolder)
		if not podiums then
			return pads
		end

		for _, podium in ipairs(podiums:GetChildren()) do
			local base = podium:FindFirstChild("Base")
			local spawn = base and base:FindFirstChild("Spawn")
			if spawn and spawn:IsA("BasePart") then
				pads[#pads + 1] = spawn
			end
		end

		return pads
	end

	local function isDescendantOfPodiums(model, podiums)
		if not podiums then
			return false
		end
		local ok, result = pcall(model.IsDescendantOf, model, podiums)
		return ok and result or false
	end

	--- Removes brainrots belonging to the local player's plot.
	--- Returns removedCount, inspectedCount.
	function PlotService.clean(plot)
		plot = plot or PlotService.findPlot()
		if not plot then
			return 0, 0
		end

		local pads = PlotService.podiumPads(plot)
		local podiums = plot:FindFirstChild(Config.Paths.PodiumsFolder)
		local characters = characterSet()
		local plotPivot = plot:GetPivot().Position

		local removed, inspected = 0, 0
		local names = {}

		for _, model in ipairs(Env.Workspace:GetChildren()) do
			if inspected >= Config.Behaviour.MaxModelsPerClean then
				Log.warn("plot", "inspection cap reached at %d models", inspected)
				break
			end

			if model:IsA("Model") then
				inspected = inspected + 1

				local ok, pivot = pcall(function()
					return model:GetPivot().Position
				end)
				if ok then
					local nearestPad = nil
					for _, pad in ipairs(pads) do
						local distance = (pivot - pad.Position).Magnitude
						if not nearestPad or distance < nearestPad then
							nearestPad = distance
						end
					end

					local remove, rule = PlotService.classify({
						name = model.Name,
						isPlayerCharacter = characters[model] == true,
						isSpawnedMarker = model:GetAttribute("KVSpawned") == true,
						inPodiumsFolder = isDescendantOfPodiums(model, podiums),
						distanceToPodium = nearestPad,
						distanceToPlot = (pivot - plotPivot).Magnitude,
						hasHumanoid = model:FindFirstChildOfClass("Humanoid") ~= nil,
						isKnownBrainrot = Config.BrainrotSet[model.Name] == true,
					})

					if remove then
						local destroyed = pcall(model.Destroy, model)
						if destroyed then
							removed = removed + 1
							names[#names + 1] = model.Name
							Log.trace("plot", "removed %s (%s)", model.Name, rule)
						end
					end
				end
			end
		end

		if removed > 0 then
			Log.info("plot", "removed %d brainrot(s): %s", removed, table.concat(names, ", "))
		else
			Log.debug("plot", "nothing to remove (%d models inspected)", inspected)
		end

		return removed, inspected
	end

	return PlotService
end

__modules["DuelService"] = function()
	--[[
		DuelService
		-----------
		Reading and rewriting the in-game duel GUI: locating the window, finding
		each slot's viewport, and rendering a brainrot model into it.
	]]

	local Catalogue = __require("Catalogue")
	local Config = __require("Config")
	local Env = __require("Env")
	local Log = __require("Log")

	local DuelService = {}

	--- Locates the duel window. Returns nil when it is closed.
	function DuelService.findGui()
		local player = Env.LocalPlayer
		local playerGui = player and player:FindFirstChild("PlayerGui")
		if not playerGui then
			return nil
		end

		local screenGui = playerGui:FindFirstChild(Config.Paths.DuelGui)
		if not screenGui then
			return nil
		end

		local inner = screenGui:FindFirstChild(Config.Paths.DuelGui)
		if not inner then
			return nil
		end

		return {
			screenGui = screenGui,
			inner = inner,
			Main = inner:FindFirstChild("Main"),
			Other = inner:FindFirstChild("Other"),
		}
	end

	--- Returns the section frame for a slot name, or nil.
	function DuelService.section(slot)
		local gui = DuelService.findGui()
		if not gui then
			return nil, "duel GUI is closed"
		end
		local section = gui[slot]
		if not section then
			return nil, "slot " .. tostring(slot) .. " not present"
		end
		return section
	end

	--- Pulls the viewport, title and cash labels out of a slot section.
	function DuelService.slotData(section)
		if not section then
			return nil
		end
		local item = section:FindFirstChild("Item")
		local viewport = item and item:FindFirstChild("ViewportFrame")
		if not viewport then
			return nil
		end

		local title = item:FindFirstChild("Title")
		local cash = item:FindFirstChild("Cash")

		return {
			section = section,
			item = item,
			viewport = viewport,
			title = title,
			cash = cash,
			name = title and title.Text or "Unknown",
			cashText = cash and cash.Text or "",
		}
	end

	--- Current contents of both slots, for the status panel.
	function DuelService.snapshot()
		local gui = DuelService.findGui()
		if not gui then
			return nil
		end

		local out = {}
		for _, slot in ipairs(Config.Slots) do
			local data = DuelService.slotData(gui[slot])
			if data then
				out[slot] = { name = data.name, cash = data.cashText }
			end
		end
		return out
	end

	------------------------------------------------------------------------------
	-- Viewport rendering
	------------------------------------------------------------------------------

	local function clearViewport(viewport)
		for _, child in ipairs(viewport:GetChildren()) do
			pcall(child.Destroy, child)
		end
	end

	DuelService.clearViewport = clearViewport

	--- Strips physics + shadows so the preview model is inert and cheap.
	local function neutralise(model)
		for _, descendant in ipairs(model:GetDescendants()) do
			if descendant:IsA("BasePart") then
				descendant.Anchored = true
				descendant.CanCollide = false
				descendant.CanQuery = false
				descendant.CanTouch = false
				descendant.CastShadow = false
			elseif descendant:IsA("Script") or descendant:IsA("LocalScript") then
				-- Never let a cloned asset run behaviour inside our preview.
				pcall(descendant.Destroy, descendant)
			end
		end
	end

	--- Frames `model` inside `camera` using its bounding box.
	local function frameModel(camera, model)
		local extents = model:GetExtentsSize()
		local maxDimension = math.max(extents.X, extents.Y, extents.Z, 1)
		local halfFov = math.rad(Config.Behaviour.FieldOfView * 0.5)
		local distance = (maxDimension * 0.5 / math.tan(halfFov)) * 0.85

		local pivot = model:GetPivot().Position
		local position = pivot + Vector3.new(-(distance + maxDimension * 0.35), extents.Y * 0.1, 0)
		local target = pivot + Vector3.new(0, extents.Y * 0.05, 0)

		camera.CFrame = CFrame.new(position, target)
	end

	local function playIdle(model, name)
		local animation = Catalogue.idleAnimation(name)
		if not animation then
			return
		end

		local controller = model:FindFirstChildOfClass("AnimationController")
		if not controller then
			controller = Instance.new("AnimationController")
			controller.Parent = model
		end

		local animator = controller:FindFirstChildOfClass("Animator")
		if not animator then
			animator = Instance.new("Animator")
			animator.Parent = controller
		end

		local ok, track = pcall(animator.LoadAnimation, animator, animation)
		if ok and track then
			track.Looped = true
			track:Play()
		end
	end

	--- Renders `name` into `viewport`. Returns true on success.
	function DuelService.render(viewport, name)
		if not viewport then
			return false
		end

		local model = Catalogue.model(name)
		if not model then
			return false
		end

		clearViewport(viewport)
		neutralise(model)

		local world = Instance.new("WorldModel")
		world.Parent = viewport

		local camera = Instance.new("Camera")
		camera.FieldOfView = Config.Behaviour.FieldOfView
		camera.Parent = viewport
		viewport.CurrentCamera = camera

		model:PivotTo(CFrame.new(0, 0, 0))
		model.Parent = world

		frameModel(camera, model)

		-- Animations need the model parented and settled for a frame.
		task.defer(function()
			pcall(playIdle, model, name)
		end)

		return true
	end

	------------------------------------------------------------------------------
	-- High level actions
	------------------------------------------------------------------------------

	--- Writes `name` into `slot`: renders the model and updates the labels.
	--- Returns ok, message.
	function DuelService.apply(slot, name)
		local section, reason = DuelService.section(slot)
		if not section then
			return false, reason
		end

		local data = DuelService.slotData(section)
		if not data then
			return false, "slot layout not recognised"
		end

		if not DuelService.render(data.viewport, name) then
			return false, "model unavailable for " .. name
		end

		local cashText = Catalogue.generationText(name)
		if data.title then
			data.title.Text = name
		end
		if data.cash then
			data.cash.Text = cashText
		end

		Log.info("duel", "%s -> %s (%s)", slot, name, cashText)
		return true, cashText
	end

	--- Restores both slots to their vanilla contents.
	function DuelService.revert()
		local gui = DuelService.findGui()
		if not gui then
			return false, "duel GUI is closed"
		end

		for slot, defaults in pairs(Config.RevertDefaults) do
			local data = DuelService.slotData(gui[slot])
			if data then
				clearViewport(data.viewport)
				if data.title then
					data.title.Text = defaults.name
				end
				if data.cash then
					data.cash.Text = defaults.cash
				end
			end
		end

		Log.info("duel", "reverted both slots")
		return true
	end

	return DuelService
end

__modules["Ui"] = function()
	--[[
		Ui
		--
		A very small widget helper layer. The goal is not a framework: it is to
		remove the ~600 lines of copy-pasted Instance.new/UICorner/UIStroke noise
		from the original file so the window code reads as layout, not plumbing.

		Every widget returns the raw Instance, so anything not covered here can
		still be done directly.
	]]

	local Config = __require("Config")
	local Env = __require("Env")

	local Theme = Config.Theme

	local Ui = {}

	--- Instance.new with a property table, tolerant of unsupported properties.
	function Ui.new(className, properties, children)
		local ok, instance = pcall(Instance.new, className)
		if not ok or not instance then
			return nil
		end

		if properties then
			-- Parent last: setting it first causes a reflow per property.
			local parent = properties.Parent
			properties.Parent = nil
			for key, value in pairs(properties) do
				pcall(function()
					instance[key] = value
				end)
			end
			if parent then
				instance.Parent = parent
			end
			properties.Parent = parent
		end

		if children then
			for _, child in ipairs(children) do
				if child then
					child.Parent = instance
				end
			end
		end

		return instance
	end

	function Ui.corner(parent, radius)
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(0, radius or Theme.CornerRadius)
		corner.Parent = parent
		return corner
	end

	function Ui.stroke(parent, colour, thickness)
		local stroke = Instance.new("UIStroke")
		stroke.Color = colour or Theme.Outline
		stroke.Thickness = thickness or 1
		stroke.Transparency = Theme.StrokeTransparency
		stroke.Parent = parent
		return stroke
	end

	function Ui.padding(parent, amount)
		local padding = Instance.new("UIPadding")
		local offset = UDim.new(0, amount or 8)
		padding.PaddingTop = offset
		padding.PaddingBottom = offset
		padding.PaddingLeft = offset
		padding.PaddingRight = offset
		padding.Parent = parent
		return padding
	end

	function Ui.list(parent, direction, gap)
		local layout = Instance.new("UIListLayout")
		layout.FillDirection = direction or Enum.FillDirection.Vertical
		layout.Padding = UDim.new(0, gap or 6)
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Parent = parent
		return layout
	end

	function Ui.label(properties)
		properties = properties or {}
		properties.BackgroundTransparency = properties.BackgroundTransparency or 1
		properties.TextColor3 = properties.TextColor3 or Theme.Text
		properties.Font = properties.Font or Enum.Font.Gotham
		properties.TextSize = properties.TextSize or 10
		properties.TextXAlignment = properties.TextXAlignment or Enum.TextXAlignment.Left
		return Ui.new("TextLabel", properties)
	end

	function Ui.heading(text, parent, order)
		return Ui.label({
			Size = UDim2.new(1, 0, 0, 14),
			Text = text,
			TextColor3 = Theme.Accent,
			Font = Enum.Font.GothamBold,
			TextSize = 8,
			LayoutOrder = order,
			Parent = parent,
		})
	end

	--- Button with hover feedback and a guarded click handler.
	function Ui.button(properties, onClick)
		properties = properties or {}
		local base = properties.BackgroundColor3 or Theme.Neutral

		properties.AutoButtonColor = false
		properties.BorderSizePixel = 0
		properties.TextColor3 = properties.TextColor3 or Theme.OnAccent
		properties.Font = properties.Font or Enum.Font.GothamBold
		properties.TextSize = properties.TextSize or 9

		local button = Ui.new("TextButton", properties)
		if not button then
			return nil
		end

		Ui.corner(button, properties.CornerRadius or 4)

		local hover = base:Lerp(Color3.new(1, 1, 1), 0.15)
		button.MouseEnter:Connect(function()
			button.BackgroundColor3 = hover
		end)
		button.MouseLeave:Connect(function()
			button.BackgroundColor3 = base
		end)

		if onClick then
			button.MouseButton1Click:Connect(function()
				-- A failing handler must not kill the button's future clicks.
				local ok, err = pcall(onClick)
				if not ok then
					__require("Log").error("ui", "button handler failed: %s", tostring(err))
				end
			end)
		end

		return button
	end

	--- Root ScreenGui, replacing any previous instance of the same name.
	function Ui.screen(name)
		local parent = Env.guiParent()

		local existing = parent and parent:FindFirstChild(name)
		if existing then
			pcall(existing.Destroy, existing)
		end

		return Ui.new("ScreenGui", {
			Name = name,
			ResetOnSpawn = false,
			IgnoreGuiInset = true,
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
			DisplayOrder = Config.Window.DisplayOrder,
			Parent = parent,
		})
	end

	--- Makes `frame` draggable by `handle`, mouse and touch.
	--- Returns a disconnect function; the original leaked a global
	--- UserInputService connection per window.
	function Ui.draggable(frame, handle)
		handle = handle or frame

		local dragging = false
		local dragStart, startPosition

		local function update(input)
			local delta = input.Position - dragStart
			frame.Position = UDim2.new(
				startPosition.X.Scale,
				startPosition.X.Offset + delta.X,
				startPosition.Y.Scale,
				startPosition.Y.Offset + delta.Y
			)
		end

		local connections = {}

		connections[#connections + 1] = handle.InputBegan:Connect(function(input)
			local kind = input.UserInputType
			if kind == Enum.UserInputType.MouseButton1 or kind == Enum.UserInputType.Touch then
				dragging = true
				dragStart = input.Position
				startPosition = frame.Position

				local changed
				changed = input.Changed:Connect(function()
					if input.UserInputState == Enum.UserInputState.End then
						dragging = false
						changed:Disconnect()
					end
				end)
			end
		end)

		connections[#connections + 1] = Env.UserInputService.InputChanged:Connect(function(input)
			if not dragging then
				return
			end
			local kind = input.UserInputType
			if kind == Enum.UserInputType.MouseMovement or kind == Enum.UserInputType.Touch then
				update(input)
			end
		end)

		return function()
			for _, connection in ipairs(connections) do
				pcall(function()
					connection:Disconnect()
				end)
			end
		end
	end

	--- Standard window chrome: draggable titlebar, close button, content frame.
	function Ui.window(screen, title, width, height)
		local frame = Ui.new("Frame", {
			Size = UDim2.new(0, width, 0, height),
			Position = UDim2.new(0.5, -width / 2, 0.25, 0),
			BackgroundColor3 = Theme.Background,
			BorderSizePixel = 0,
			Active = true,
			Parent = screen,
		})
		Ui.corner(frame, 8)
		Ui.stroke(frame, Theme.Outline, 1.5)

		local titlebar = Ui.new("Frame", {
			Size = UDim2.new(1, 0, 0, Config.Window.TitlebarHeight),
			BackgroundColor3 = Theme.Titlebar,
			BackgroundTransparency = 0.2,
			BorderSizePixel = 0,
			Parent = frame,
		})
		Ui.corner(titlebar, 8)

		Ui.label({
			Size = UDim2.new(1, -40, 1, 0),
			Position = UDim2.new(0, 12, 0, 0),
			Text = title,
			Font = Enum.Font.GothamBlack,
			TextSize = 12,
			Parent = titlebar,
		})

		Ui.button({
			Size = UDim2.new(0, 24, 0, 24),
			Position = UDim2.new(1, -30, 0.5, -12),
			BackgroundColor3 = Theme.Danger,
			Text = "✕",
			TextSize = 12,
			Parent = titlebar,
		}, function()
			screen:Destroy()
		end)

		local content = Ui.new("Frame", {
			Size = UDim2.new(1, 0, 1, -Config.Window.TitlebarHeight),
			Position = UDim2.new(0, 0, 0, Config.Window.TitlebarHeight),
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Parent = frame,
		})
		Ui.padding(content, 10)
		Ui.list(content, Enum.FillDirection.Vertical, 6)

		local disconnectDrag = Ui.draggable(frame, titlebar)
		screen.Destroying:Connect(disconnectDrag)

		return frame, content, titlebar
	end

	return Ui
end

__modules["Tester"] = function()
	--[[
		Tester
		------
		The receiving side. This file did not exist before: `Tester side` in the
		repository root was a single empty byte, so nothing ever consumed the
		admin's broadcast.

		Responsibilities:
		  * listen on every available transport
		  * apply accepted payloads to the local duel GUI
		  * show link health so the operator can tell "idle" from "broken"
	]]


	local Config = __require("Config")
	local DuelService = __require("DuelService")
	local Log = __require("Log")
	local Sync = __require("Sync")
	local Ui = __require("Ui")
	local Util = __require("Util")

	local Theme = Config.Theme

	local Tester = {}

	local WINDOW_HEIGHT = 200

	function Tester.start()
		local sync = Sync.new()

		local screen = Ui.screen(Config.APP_NAME .. "Tester")
		if not screen then
			Log.error("tester", "could not create ScreenGui")
			return
		end

		local _, content = Ui.window(
			screen,
			"📡 Duel Receiver " .. Config.VERSION,
			320,
			WINDOW_HEIGHT
		)

		----------------------------------------------------------------------
		-- Link status
		----------------------------------------------------------------------

		Ui.heading("LINK", content, 1)

		local linkRow = Ui.new("Frame", {
			Size = UDim2.new(1, 0, 0, 34),
			BackgroundColor3 = Theme.SurfaceAlt,
			BorderSizePixel = 0,
			LayoutOrder = 2,
			Parent = content,
		})
		Ui.corner(linkRow, 5)
		Ui.stroke(linkRow)

		local dot = Ui.new("Frame", {
			Size = UDim2.new(0, 8, 0, 8),
			Position = UDim2.new(0, 10, 0.5, -4),
			BackgroundColor3 = Theme.Danger,
			BorderSizePixel = 0,
			Parent = linkRow,
		})
		Ui.corner(dot, 4)

		local linkLabel = Ui.label({
			Size = UDim2.new(1, -30, 1, 0),
			Position = UDim2.new(0, 26, 0, 0),
			Text = "Waiting for admin…",
			TextColor3 = Theme.SubText,
			TextSize = 9,
			Parent = linkRow,
		})

		----------------------------------------------------------------------
		-- Received slots
		----------------------------------------------------------------------

		Ui.heading("RECEIVED", content, 3)

		local slotPanel = Ui.new("Frame", {
			Size = UDim2.new(1, 0, 0, 46),
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			LayoutOrder = 4,
			Parent = content,
		})
		Ui.list(slotPanel, Enum.FillDirection.Horizontal, 6)

		local cards = {}

		for index, slot in ipairs(Config.Slots) do
			local accent = slot == "Main" and Theme.Accent or Theme.Gold

			local frame = Ui.new("Frame", {
				Size = UDim2.new(0.5, -3, 1, 0),
				BackgroundColor3 = Theme.SurfaceAlt,
				BorderSizePixel = 0,
				LayoutOrder = index,
				Parent = slotPanel,
			})
			Ui.corner(frame, 5)
			Ui.stroke(frame)

			Ui.label({
				Size = UDim2.new(1, -10, 0, 12),
				Position = UDim2.new(0, 8, 0, 4),
				Text = slot:upper(),
				TextColor3 = accent,
				Font = Enum.Font.GothamBold,
				TextSize = 7,
				Parent = frame,
			})

			cards[slot] = Ui.label({
				Size = UDim2.new(1, -10, 0, 18),
				Position = UDim2.new(0, 8, 0, 20),
				Text = "—",
				TextColor3 = Theme.SubText,
				Font = Enum.Font.GothamBold,
				TextSize = 10,
				Parent = frame,
			})
		end

		local status = Ui.label({
			Size = UDim2.new(1, 0, 0, 16),
			Text = "",
			TextColor3 = Theme.SubText,
			TextSize = 9,
			TextXAlignment = Enum.TextXAlignment.Center,
			LayoutOrder = 5,
			Parent = content,
		})

		----------------------------------------------------------------------
		-- Applying inbound payloads
		----------------------------------------------------------------------

		local received = 0

		sync.received:connect(function(payload)
			received = received + 1

			local card = cards[payload.slot]

			if payload.brainrot == "" then
				-- Documented "clear this slot" instruction.
				local section = DuelService.section(payload.slot)
				local data = section and DuelService.slotData(section)
				if data then
					DuelService.clearViewport(data.viewport)
					local defaults = Config.RevertDefaults[payload.slot]
					if defaults then
						if data.title then
							data.title.Text = defaults.name
						end
						if data.cash then
							data.cash.Text = defaults.cash
						end
					end
				end
				if card then
					card.Text = "cleared"
					card.TextColor3 = Theme.SubText
				end
				status.Text = string.format("↩️ %s cleared", payload.slot)
				status.TextColor3 = Theme.SubText
				return
			end

			local applied, detail = DuelService.apply(payload.slot, payload.brainrot)

			if card then
				card.Text = Util.truncate(payload.brainrot, 15)
				card.TextColor3 = applied and Theme.Text or Theme.Danger
			end

			if applied then
				status.Text = string.format("✅ %s → %s", payload.slot, payload.brainrot)
				status.TextColor3 = Theme.Success
			else
				status.Text = string.format("❌ %s", detail)
				status.TextColor3 = Theme.Danger
				Log.warn("tester", "could not apply %s: %s", payload.brainrot, tostring(detail))
			end
		end)

		sync.rejected:connect(function(_, reason)
			Log.debug("tester", "dropped payload: %s", reason)
		end)

		----------------------------------------------------------------------
		-- Link health loop
		----------------------------------------------------------------------

		local function transportNames()
			local ids = {}
			for _, transport in ipairs(sync:activeTransports()) do
				ids[#ids + 1] = transport.id
			end
			return #ids > 0 and table.concat(ids, "+") or "none"
		end

		sync:listen()

		task.spawn(function()
			while screen.Parent do
				local stale = sync:isStale()
				local last = sync:last()

				if not last then
					dot.BackgroundColor3 = Theme.Warning
					linkLabel.Text = string.format("Listening on %s · no data yet", transportNames())
					linkLabel.TextColor3 = Theme.SubText
				elseif stale then
					dot.BackgroundColor3 = Theme.Danger
					linkLabel.Text = string.format("Stale · last update >%ds ago", Config.Behaviour.StaleAfter)
					linkLabel.TextColor3 = Theme.Danger
				else
					dot.BackgroundColor3 = Theme.Success
					linkLabel.Text = string.format("Connected · %s · %d msg", transportNames(), received)
					linkLabel.TextColor3 = Theme.Success
				end

				task.wait(1)
			end
			sync:destroy()
		end)

		Log.info("tester", "%s receiver v%s ready (session %s)",
			Config.APP_NAME, Config.VERSION, sync.session)

		return {
			sync = sync,
			screen = screen,
		}
	end

	return Tester
end


return __require("Tester").start()
